    component Layer is
        generic(weight_array_size : integer := 10);
        Port(
                clock_L :  in  std_logic;
                Enable_L : in STD_LOGIC;
                Reset_L :  in STD_LOGIC;
                Input_L :  in std_logic_vector (31 downto 0);
                Valid_L :  out STD_LOGIC;
                Output_L : out std_logic_vector (31 downto 0)
             );
    end component;

begin

    laye: Layer port map(
       Enable_L    =>      ENABLE,
       Input_L     =>      INPUT,
       clock_L     =>      CLOCK, 
       Reset_L     =>      RESET,
       Valid_L     =>      VALID,
       Output_L    =>      OUTPUT
    );
    
    CLOCK <= not CLOCK after 5 ns;
    stimulus: process
    begin
        ENABLE <= '0';
        RESET <= '0';
        wait for 20 ns;
        RESET <= '1';
        wait for 20 ns;
        ENABLE <= '1';
        for i in 0 to 783 loop
            INPUT <= my_digit(i);
            wait for 20 ns;
        end loop;        
        wait;
    end process;
end Bench;
